package com.yupi.template.storage;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.boot.test.context.runner.ApplicationContextRunner;import org.springframework.boot.autoconfigure.AutoConfigurations;import org.springframework.boot.autoconfigure.context.ConfigurationPropertiesAutoConfiguration;import org.springframework.boot.env.YamlPropertySourceLoader;import org.springframework.core.io.ClassPathResource;import com.yupi.template.config.NanoBananaConfig;import com.yupi.template.config.CosConfig;import com.yupi.template.service.CosService;
class A4StorageBindingTest {
 @Test void realProductionBindingWithoutCos(){new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(ConfigurationPropertiesAutoConfiguration.class)).withUserConfiguration(NanoBananaConfig.class,CosConfig.class,CosService.class,LocalImageStorage.class,CosImageStorage.class).withInitializer(c->{try{for(var source:new YamlPropertySourceLoader().load("prod",new ClassPathResource("application-prod.yml")))c.getEnvironment().getPropertySources().addLast(source);}catch(Exception e){throw new RuntimeException(e);}}).withPropertyValues("IMAGE_MODEL_API_KEY=isolated-image-key","IMAGE_MODEL=gemini-3-pro-image","IMAGE_MODEL_BASE_URL=https://generativelanguage.googleapis.com").run(c->{assertNull(c.getStartupFailure());assertEquals("isolated-image-key",c.getBean(NanoBananaConfig.class).getApiKey());assertEquals("gemini-3-pro-image",c.getBean(NanoBananaConfig.class).getModel());assertEquals(0,c.getBeansOfType(CosService.class).size());assertEquals(0,c.getBeansOfType(CosImageStorage.class).size());assertEquals(1,c.getBeansOfType(ImageStorage.class).size());});}
}
